static List<Map.Entry<String, Integer>> top3Loop(String text) {
    Map<String, Integer> counts = new HashMap<>();
    for (String w : text.toLowerCase().split("[^\\p{L}\\p{N}]+")) {
        if (!w.isEmpty()) counts.merge(w, 1, Integer::sum);
    }
    List<Map.Entry<String, Integer>> entries = new ArrayList<>(counts.entrySet());
    entries.sort(Map.Entry.<String, Integer>comparingByValue().reversed()
        .thenComparing(Map.Entry.comparingByKey()));
    return entries.subList(0, Math.min(3, entries.size()));
}

static List<Map.Entry<String, Long>> top3Stream(String text) {
    return Arrays.stream(text.toLowerCase().split("[^\\p{L}\\p{N}]+"))
        .filter(w -> !w.isEmpty())
        .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()))
        .entrySet().stream()
        .sorted(Map.Entry.<String, Long>comparingByValue().reversed()
            .thenComparing(Map.Entry.comparingByKey()))
        .limit(3)
        .toList();
}

