@Service
public class TransferService {
    private final AccountRepository accounts;
    private final AuditService audit;
    private final ApplicationEventPublisher events;

    TransferService(AccountRepository accounts, AuditService audit, ApplicationEventPublisher events) {
        this.accounts = accounts; this.audit = audit; this.events = events;
    }

    @Transactional(rollbackFor = Exception.class)   // rollback cả checked exception
    public void transfer(long from, long to, long amount) throws InsufficientFundsException {
        audit.log("transfer " + from + " -> " + to);     // REQUIRES_NEW: lưu dù có rollback
        Account a = accounts.findById(from).orElseThrow();
        Account b = accounts.findById(to).orElseThrow();
        if (a.getBalance() < amount) throw new InsufficientFundsException();   // checked
        a.withdraw(amount);
        b.deposit(amount);
        events.publishEvent(new TransferDone(from, to, amount));   // xử lý sau khi commit
    }
}

