@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock OrderRepository repo;
    @Mock Notifier notifier;
    @InjectMocks OrderService service;

    @Test
    void cancel_paidOrder_setsCancelledAndNotifies() {
        Order o = new Order(1L, OrderStatus.PAID, "an@example.vn");
        when(repo.findById(1L)).thenReturn(Optional.of(o));            // given

        service.cancel(1L);                                              // when

        assertEquals(OrderStatus.CANCELLED, o.getStatus());              // then
        verify(notifier).send(eq("an@example.vn"), contains("huỷ"));
    }

    @Test
    void cancel_deliveredOrder_throws() {
        when(repo.findById(2L)).thenReturn(Optional.of(new Order(2L, OrderStatus.DELIVERED, "b@x.vn")));
        assertThrows(ConflictException.class, () -> service.cancel(2L));
        verifyNoInteractions(notifier);
    }
}

