@Service
class ShippingService {
    private final RestClient client;
    ShippingService(RestClient shippingClient) { this.client = shippingClient; }

    @CircuitBreaker(name = "shipping", fallbackMethod = "flatFee")
    @Retry(name = "shipping")                                    // GET tính phí: idempotent
    public long fee(String province, int weightGram) {
        return client.get()
            .uri("/fee?province={p}&weight={w}", province, weightGram)
            .retrieve()
            .body(FeeResponse.class)
            .amount();
    }

    long flatFee(String province, int weightGram, Throwable e) { return 30_000; }   // dự phòng
}

