// WebFlux: non-blocking từ đầu tới cuối
@RestController
class PriceStream {
    private final ReactivePriceRepository repo;    // R2DBC, không phải JPA
    PriceStream(ReactivePriceRepository repo) { this.repo = repo; }

    @GetMapping(value = "/prices/stream", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    Flux<Price> stream() {
        return Flux.interval(Duration.ofSeconds(1))
            .flatMap(t -> repo.findLatest())        // Mono<Price>
            .onBackpressureDrop();
    }

    @GetMapping("/prices/{id}")
    Mono<Price> one(@PathVariable long id) { return repo.findById(id); }
}

